const Gallery: React.FC = () => {
  const imageRefs = useRef<(HTMLImageElement | null)[]>([]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const img = entry.target as HTMLImageElement;
            const src = img.getAttribute('data-src');

            if (src) {
              img.src = src;
              img.removeAttribute('data-src');
              observer.unobserve(img);
            }
          }
        });
      },
      {
        rootMargin: '50px',
        threshold: 0.1,
      }
    );

    imageRefs.current.forEach((img) => {
      if (img) observer.observe(img);
    });

    return () => {
      observer.disconnect();
    };
  }, []);

  const handleLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    e.currentTarget.classList.add('loaded');
  };

  return (
    <section id="galeria" className="py-24 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <h2 className="text-4xl md:text-5xl font-bold mb-4 text-gray-800">Galeria da Carretinha <span className="inline-block animate-bounce-gentle">📸</span></h2>
        <p className="text-xl text-gray-600 mb-12 font-medium">Confira cada cantinho do nosso playground móvel!</p>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10 px-4">
          {images.map((img, index) => (
            <div 
              key={index}
              className={`group relative aspect-video p-2 bg-white rounded-xl shadow-lg border-2 border-gray-100 transition-all hover:shadow-2xl hover:scale-105 hover:z-10 transform ${index % 2 === 0 ? 'rotate-1' : '-rotate-1'}`}
