        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 md:gap-8">
          {images.map((img, index) => (
            <div 
              key={index}
              onClick={() => setSelectedIndex(index)}
              className="group relative aspect-square sm:aspect-video overflow-hidden rounded-3xl sm:rounded-[2.5rem] cursor-pointer shadow-md sm:shadow-lg border-2 sm:border-4 border-pink-50 transition-all hover:shadow-2xl bg-pink-50/50 hover:border-pink-200 shimmer-bg"
            >
              <img 
                ref={(el) => {
                  if (el) imageRefs.current[index] = el;
                }}
                data-src={img.url}
                alt="Carretinha"
                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110 lazy-image"
                width="640"
