                decoding="async"
                onLoad={handleLoad}
              />
              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center">
                 <div className="bg-white/95 p-3 rounded-full text-pink-500 transform scale-0 group-hover:scale-100 transition-transform duration-300 flex items-center space-x-2">
