const Gallery: React.FC = () => {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [modalImageLoaded, setModalImageLoaded] = useState(false);

  const touchStartX = useRef<number>(0);
  const touchEndX = useRef<number>(0);

  const isFirst = selectedIndex === 0;
  const isLast = selectedIndex === images.length - 1;

  const handleNext = useCallback((e?: React.MouseEvent | React.TouchEvent) => {
    e?.stopPropagation();
    if (selectedIndex !== null && !isLast) {
      setModalImageLoaded(false);
      setSelectedIndex(selectedIndex + 1);
    }
  }, [selectedIndex, isLast]);

  const handlePrev = useCallback((e?: React.MouseEvent | React.TouchEvent) => {
    e?.stopPropagation();
    if (selectedIndex !== null && !isFirst) {
      setModalImageLoaded(false);
      setSelectedIndex(selectedIndex - 1);
    }
  }, [selectedIndex, isFirst]);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const handleTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const diff = touchStartX.current - touchEndX.current;
    if (diff > 50) handleNext();
    else if (diff < -50) handlePrev();
    touchStartX.current = 0;
    touchEndX.current = 0;
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === 'Escape') setSelectedIndex(null);
      if (e.key === 'ArrowRight') handleNext();
      if (e.key === 'ArrowLeft') handlePrev();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, handleNext, handlePrev]);

  // Bloqueio de scroll aprimorado
  useEffect(() => {
    if (selectedIndex !== null) {
      document.body.style.position = 'fixed';
      document.body.style.width = '100%';
      document.body.style.top = `-${window.scrollY}px`;
    } else {
      const scrollY = document.body.style.top;
      document.body.style.position = '';
      document.body.style.width = '';
      document.body.style.top = '';
      if (scrollY) window.scrollTo(0, parseInt(scrollY || '0') * -1);
    }
  }, [selectedIndex]);

  const currentImage = selectedIndex !== null ? images[selectedIndex] : null;

  return (
    <section id="galeria" className="py-24 bg-white relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <h2 className="text-4xl md:text-5xl font-bold mb-4 text-gray-800 uppercase tracking-tight">
          Nossa Galeria <span className="inline-block animate-bounce-gentle">📸</span>
        </h2>
        <p className="text-xl text-gray-600 mb-12">Arraste ou clique para ver mais! ✨</p>

        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 md:gap-8">
          {images.map((img, index) => (
            <div 
              key={index}
              onClick={() => {
                setModalImageLoaded(false);
                setSelectedIndex(index);
              }}
              className="group relative aspect-square overflow-hidden rounded-3xl cursor-pointer shadow-md transition-all bg-pink-50 border-2 md:border-4 border-white"
            >
              <img 
                src={img.url}
                alt={img.alt}
                className="w-full h-full object-cover transition-opacity duration-300 group-hover:scale-110 opacity-0"
                loading="lazy"
                onLoad={(e) => e.currentTarget.classList.add('opacity-100')}
              />
              <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <ZoomIn className="text-white drop-shadow-lg" size={32} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* MODAL RECONSTRUÍDO DO ZERO */}
      {currentImage && (
        <div 
          className="fixed inset-0 z-[9999] bg-black/95 flex flex-col items-center justify-center overflow-hidden touch-none"
          onClick={() => setSelectedIndex(null)}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          {/* CAMADA SUPERIOR: HEADER (ABSOLUTO) */}
          <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-center z-[10001] pointer-events-none">
            <div className="bg-white/10 backdrop-blur-md text-white px-5 py-2 rounded-full font-bold text-sm pointer-events-auto border border-white/20">
              {selectedIndex! + 1} / {images.length}
            </div>
            <button 
              className="bg-white/10 hover:bg-white/20 text-white p-3 rounded-full transition-all pointer-events-auto border border-white/20"
              onClick={(e) => { e.stopPropagation(); setSelectedIndex(null); }}
            >
              <X size={28} />
            </button>
          </div>

          {/* CAMADA CENTRAL: IMAGEM (CENTRO REAL USANDO FLEXBOX E DVH) */}
          <div className="w-full h-[100dvh] flex items-center justify-center p-4 sm:p-12 relative pointer-events-none">
            {!modalImageLoaded && (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-12 h-12 border-4 border-pink-500/20 border-t-pink-500 rounded-full animate-spin"></div>
              </div>
            )}

            <img 
              key={currentImage.url}
              src={currentImage.url} 
              alt={currentImage.alt} 
              className={`max-w-full max-h-[75dvh] sm:max-h-[85vh] object-contain rounded-xl shadow-2xl transition-all duration-300 pointer-events-auto ${modalImageLoaded ? 'opacity-100 scale-100' : 'opacity-0 scale-95'}`}
              onLoad={() => setModalImageLoaded(true)}
              onClick={(e) => e.stopPropagation()}
            />

            {/* Setas Desktop laterais */}
            <div className="absolute inset-0 hidden lg:flex items-center justify-between px-8 pointer-events-none">
              {!isFirst && (
                <button className="bg-white/10 hover:bg-white/20 text-white p-4 rounded-full pointer-events-auto border border-white/10" onClick={handlePrev}><ChevronLeft size={40} /></button>
              )}
              {!isLast && (
                <button className="bg-white/10 hover:bg-white/20 text-white p-4 rounded-full pointer-events-auto border border-white/10" onClick={handleNext}><ChevronRight size={40} /></button>
              )}
            </div>
          </div>

          {/* CAMADA INFERIOR: LEGENDA (ABSOLUTO) */}
          <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-black via-black/80 to-transparent pt-32 pb-10 px-6 text-center z-[10001] pointer-events-none">
            <div className="max-w-2xl mx-auto pointer-events-auto">
              <h3 className="text-2xl sm:text-3xl font-kids font-bold text-white mb-2 drop-shadow-lg">{currentImage.title}</h3>
              <p className="text-gray-300 text-base sm:text-lg leading-snug drop-shadow-md">{currentImage.description}</p>
            </div>
          </div>

          {/* ÁREAS DE TOQUE LATERAIS PARA MOBILE */}
          <div className="absolute inset-y-0 left-0 w-1/4 z-[10002] lg:hidden" onClick={handlePrev}></div>
          <div className="absolute inset-y-0 right-0 w-1/4 z-[10002] lg:hidden" onClick={handleNext}></div>
        </div>
      )}
    </section>
  );
};

